const { [ 'hu' ]: translations } = {"hu":{"dictionary":{"Copy selected content":"Kiválasztott tartalom másolása","Paste content":"Tartalom beillesztése","Paste content as plain text":"Tartalom másolása egyszerű szövegként"}}};
